// Cache store name for API responses.
export const API_CACHE_NAME = 'sgvs-api-offline-v1';
// Time after whitch cached API response is considered stale and become first to evict on new response with no available space.
export const API_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours
// Max space that may be used by the API cache. Eviction will occur if adding a new entry would exceed this limit.
export const MAX_CACHE_BYTES = 50 * 1024 * 1024; // 50 MB

// Image cache is separate from API cache to allow different TTL and size limits, and to avoid evicting API responses when adding large images.
export const IMAGE_CACHE_NAME = 'offline-images-v1';
// Time after whitch cached image response is considered stale and become first to evict on new image response with no available space.
export const IMAGE_CACHE_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days
// Max space that may be used by the image cache. Eviction will occur if adding a new image would exceed this limit.
export const MAX_IMAGE_CACHE_BYTES = 100 * 1024 * 1024; // 100 MB

// Time interval for prefetching offline data in the background when the app is opened or comes to foreground. Prefetching will be skipped if the last prefetch was done within this interval.
export const PREFETCH_INTERVAL = 4 * 60 * 60 * 1000; // 4 hours
