/// <reference lib="webworker" />
import { IMAGE_CACHE_NAME, IMAGE_CACHE_TTL, MAX_IMAGE_CACHE_BYTES } from '~/config/cache';

declare let self: ServiceWorkerGlobalScope;
console.log('[Service Worker] Registered');

// Take control of all pages immediately
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

// Reset image cache promise when main thread clears caches
self.addEventListener('message', (event) => {
  if (event.data === 'CACHE_CLEARED') {
    imageCachePromise = null;
  }
});

const IMAGE_EXTENSIONS = /\.(jpe?g|png|webp|gif|svg|avif|bmp|ico)(\?|$)/i;

function isImageUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname;
    return IMAGE_EXTENSIONS.test(pathname);
  } catch {
    return false;
  }
}

function normalizeImageUrl(url: string): string {
  const parsed = new URL(url);
  for (const key of [...parsed.searchParams.keys()]) {
    if (
      key.startsWith('X-Amz-') ||
      ['AWSAccessKeyId', 'token', 'Expires', 'Signature', 'Policy', 'Key-Pair-Id'].includes(key)
    ) {
      parsed.searchParams.delete(key);
    }
  }
  return parsed.toString();
}

let _evictLock: Promise<void> = Promise.resolve();
function withEvictLock<T>(fn: () => Promise<T>): Promise<T> {
  const prev = _evictLock;
  let resolve: () => void;
  _evictLock = new Promise<void>((r) => {
    resolve = r;
  });
  return prev.then(fn).finally(() => resolve!());
}

let imageCachePromise: Promise<Cache> | null = null;
function getImageCache(): Promise<Cache> {
  if (!imageCachePromise) {
    imageCachePromise = caches.open(IMAGE_CACHE_NAME);
  }
  return imageCachePromise;
}

const H_SIZE = 'X-Cache-Size';
const H_TIMESTAMP = 'X-Cache-Timestamp';

interface ImageCacheEntry {
  url: string;
  size: number;
  timestamp: number;
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

async function listImageEntries(): Promise<{ entries: ImageCacheEntry[]; total: number }> {
  const cache = await getImageCache();
  const requests = await cache.keys();
  const entries: ImageCacheEntry[] = [];
  let total = 0;

  for (const req of requests) {
    const res = await cache.match(req);
    if (!res) continue;
    const size = parseInt(res.headers.get(H_SIZE) ?? '0', 10);
    const timestamp = parseInt(res.headers.get(H_TIMESTAMP) ?? '0', 10);
    total += size;
    entries.push({ url: req.url, size, timestamp });
  }

  return { entries, total };
}

const env = import.meta.env.NUXT_PUBLIC_ENVIRONMENT || 'local';

async function logImageCacheDebug(label: string): Promise<void> {
  const { entries, total } = await listImageEntries();
  if (env === 'local' || env === 'development') {
    console.debug(
      `[image-cache] ${label} — cache: ${formatBytes(total)} / ${formatBytes(MAX_IMAGE_CACHE_BYTES)} (${entries.length} entries)`
    );
  }
}

async function evictImageCacheIfNeeded(incomingSize: number): Promise<void> {
  const { entries, total } = await listImageEntries();
  const cache = await getImageCache();
  const now = Date.now();
  // 1. Remove expired entries first
  const expired = entries.filter((e) => now - e.timestamp >= IMAGE_CACHE_TTL);
  let freed = 0;
  for (const entry of expired) {
    await cache.delete(new Request(entry.url));
    if (env === 'local' || env === 'development') {
      console.debug(`[image-cache] expired ${entry.url} (${formatBytes(entry.size)})`);
    }
    freed += entry.size;
  }

  // 2. If still over budget, evict oldest valid entries
  let needed = total - freed + incomingSize - MAX_IMAGE_CACHE_BYTES;
  if (needed <= 0) return;

  const valid = entries.filter((e) => now - e.timestamp < IMAGE_CACHE_TTL).sort((a, b) => a.timestamp - b.timestamp);

  for (const entry of valid) {
    if (needed <= 0) break;
    await cache.delete(new Request(entry.url));
    if (env === 'local' || env === 'development') {
      console.debug(`[image-cache] evicted ${entry.url} (${formatBytes(entry.size)})`);
    }
    needed -= entry.size;
  }
}

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET' || !isImageUrl(event.request.url)) return;

  const normalizedUrl = normalizeImageUrl(event.request.url);

  event.respondWith(
    fetch(event.request)
      .then(async (response) => {
        try {
          const cache = await getImageCache();
          const clone = response.clone();
          const body = await clone.blob();
          const size = body.size;

          await withEvictLock(async () => {
            await evictImageCacheIfNeeded(size);

            const headers = new Headers(clone.headers);
            headers.set(H_TIMESTAMP, Date.now().toString());
            headers.set(H_SIZE, String(size));
            await cache.put(new Request(normalizedUrl), new Response(body, { headers }));
            await logImageCacheDebug(`stored ${normalizedUrl} (${formatBytes(size)})`);
          });
        } catch (e) {
          console.warn('[image-cache] failed to cache image:', e);
        }
        return response;
      })
      .catch(async () => {
        const cache = await getImageCache();
        const cached = await cache.match(new Request(normalizedUrl));
        if (cached) {
          const timestamp = Number(cached.headers.get(H_TIMESTAMP) || 0);
          if (Date.now() - timestamp < IMAGE_CACHE_TTL) {
            return cached;
          }
        }
        return new Response('', { status: 404 });
      })
  );
});
